-- Entity persona types, copied from the live backend's entity persona classification (read-only, 29 Oct 2026)
CREATE TEMP TABLE pt_src (slug text, display_name text, parent_slug text, depth int, description text);
SELECT slug, display_name, 'Entity', depth, description FROM pt_src;
UPDATE persona_type p SET parent_id = par.persona_type_id
  FROM pt_src s JOIN persona_type par ON par.slug = s.parent_slug
 WHERE p.slug = s.slug;
DROP TABLE pt_src;

